<?php declare(strict_types=1);require_once __DIR__.'/auth.php';$u=portal_require();$q=$db->prepare('SELECT client_id FROM client_portal_users WHERE id=?');$q->execute([$u['id']]);$client=(int)$q->fetchColumn();$q=$db->prepare('SELECT id,name,status,start_date,end_date FROM client_projects WHERE client_id=? ORDER BY updated_at DESC');$q->execute([$client]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projects</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container py-4"><a href="index.php">← Dashboard</a><h1 class="h3 mt-3">Projects</h1><table class="table"><thead><tr><th>Project</th><th>Status</th><th>Start</th><th>End</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name']??'')?></td><td><?=htmlspecialchars($r['status']??'')?></td><td><?=htmlspecialchars($r['start_date']??'')?></td><td><?=htmlspecialchars($r['end_date']??'')?></td></tr><?php endforeach;?></tbody></table></main></body></html>